/**
 * A fixture map with a known printed grid, for alignment tests. Describes
 * the geometry of `e2e/fixtures/grid-map.png` (generated by
 * `npm run fixture:grid`): a 400×300 image whose grid lines are
 * drawn every 50 px starting 12 px in from the left and 7 px from the top.
 * Unit tests use the numbers; e2e tests can load the image.
 */
import type { GridGeometry } from "../state/model";
import type { Point } from "../map/viewport";

export const GRID_FIXTURE = {
  width: 400,
  height: 300,
  geometry: { cellSize: 50, offsetX: 12, offsetY: 7 } satisfies GridGeometry,
} as const;

/** The two opposite corners (top-left, bottom-right) of cell (column, row). */
export function fixtureSquareCorners(column: number, row: number): [Point, Point] {
  const { cellSize, offsetX, offsetY } = GRID_FIXTURE.geometry;
  const x = offsetX + column * cellSize;
  const y = offsetY + row * cellSize;
  return [
    { x, y },
    { x: x + cellSize, y: y + cellSize },
  ];
}
